#!/usr/bin/env python3
"""Audit a conda env prefix for files that diverge from conda's records.

conda-pack ships the conda-meta recorded view of each package, so a file
make-installed over the prefix without updating conda-meta is shipped as the
stale recorded bytes against the respun libs, a bin-vs-lib skew in the tarball.
This checks for that before packing.

It compares file size to the recorded size, not bytes: conda null-pads binary
prefix substitution, so size is stable under relocation and a mismatch is a real
overlay. More robust than a byte diff against a clone, which is all baked-path
noise.

  modified  - on-disk size differs from the conda-meta record. Fails the audit.
  missing   - a recorded file is absent from the prefix. Warn by default.
  untracked - a lib or executable under lib/ or bin/ owned by no package. Warn.
"""

import argparse
import json
import os
import stat
import sys

# Text files with a prefix placeholder change size when relocated, so size is
# not a valid check for them. Binary substitution is null-padded (size stable).
def is_size_checkable(rec):
    if rec.get("type") in ("softlink", "hardlink") and rec.get("size") is None:
        return False
    if rec.get("size") is None:
        return False
    if rec.get("placeholder") and rec.get("mode") == "text":
        return False
    return True


# Bytecode caches are regenerated by the interpreter, so ignore them.
def is_bytecode(rel):
    return rel.endswith(".pyc") or "/__pycache__/" in rel or rel.startswith("__pycache__/")


def load_records(meta_dir):
    # A path can be claimed by more than one package, with a different recorded
    # size each. Keep all claimants and later accept a file matching any.
    recs = {}
    for fn in os.listdir(meta_dir):
        if not fn.endswith(".json"):
            continue
        try:
            d = json.load(open(os.path.join(meta_dir, fn)))
        except Exception:
            continue
        pkg = fn[:-5]
        paths = (d.get("paths_data") or {}).get("paths")
        if paths:
            for p in paths:
                rel = p.get("_path")
                if rel is None or is_bytecode(rel):
                    continue
                recs.setdefault(rel, []).append({
                    "pkg": pkg,
                    "size": p.get("size_in_bytes"),
                    "mode": p.get("file_mode"),
                    "placeholder": p.get("prefix_placeholder"),
                    "type": p.get("path_type"),
                })
        else:
            for rel in d.get("files", []):
                if is_bytecode(rel):
                    continue
                recs.setdefault(rel, []).append({"pkg": pkg, "size": None,
                                                 "mode": None, "placeholder": None,
                                                 "type": None})
    return recs


def is_exec_or_lib(path):
    base = os.path.basename(path)
    if ".so" in base or base.endswith(".dylib"):
        return True
    try:
        st = os.lstat(path)
    except OSError:
        return False
    if stat.S_ISLNK(st.st_mode):
        return False
    return bool(st.st_mode & 0o111) and stat.S_ISREG(st.st_mode)


def main():
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("prefix", help="conda env prefix to audit")
    ap.add_argument("--fatal-missing", action="store_true",
                    help="also fail on recorded files missing from the prefix")
    ap.add_argument("--fatal-untracked", action="store_true",
                    help="also fail on untracked libs or executables")
    ap.add_argument("--scan-dirs", default="lib,bin,lib/csmplugins",
                    help="comma-separated dirs to scan for untracked libs or execs")
    args = ap.parse_args()

    prefix = os.path.abspath(args.prefix)
    meta_dir = os.path.join(prefix, "conda-meta")
    if not os.path.isdir(meta_dir):
        print(f"fail: no conda-meta in {prefix}", file=sys.stderr)
        return 2

    recs = load_records(meta_dir)

    # Compare to the conda-meta recorded size, set after relocation, not to the
    # package cache copy, which is pre-relocation and differs for every relocated
    # binary.
    modified, missing = [], []
    for rel, claimants in recs.items():
        full = os.path.join(prefix, rel)
        pkgs = "/".join(sorted({c["pkg"] for c in claimants}))
        if not os.path.lexists(full):
            # Per-package self-test fixtures live here and are never packed.
            if not rel.startswith("etc/conda/test-files/"):
                missing.append((rel, pkgs))
            continue
        if os.path.islink(full):
            continue
        checkable = [c["size"] for c in claimants if is_size_checkable(c)]
        if not checkable:
            continue
        try:
            actual = os.path.getsize(full)
        except OSError:
            continue
        # Accept if the file matches any claimant's recorded size.
        if actual not in checkable:
            modified.append((rel, pkgs, "/".join(str(s) for s in checkable), actual))

    tracked = set(recs.keys())
    untracked = []
    for d in args.scan_dirs.split(","):
        d = d.strip()
        base = os.path.join(prefix, d)
        if not os.path.isdir(base):
            continue
        for root, _dirs, files in os.walk(base):
            if "__pycache__" in root:
                continue
            for f in files:
                full = os.path.join(root, f)
                rel = os.path.relpath(full, prefix)
                if rel in tracked:
                    continue
                if is_exec_or_lib(full):
                    untracked.append(rel)

    def section(title, rows, fmt):
        print(f"\n=== {title}: {len(rows)} ===")
        for r in sorted(rows):
            print("  " + fmt(r))

    section("modified (on-disk size differs from conda-meta record)",
            modified,
            lambda r: f"{r[0]}  [{r[1]}]  recorded={r[2]} on-disk={r[3]}")
    section("missing (recorded file absent from prefix)", missing,
            lambda r: f"{r[0]}  [{r[1]}]")
    section("untracked (lib or exec owned by no package)", untracked,
            lambda r: r)

    fail = bool(modified)
    if args.fatal_missing and missing:
        fail = True
    if args.fatal_untracked and untracked:
        fail = True

    print()
    if fail:
        print("result: fail - env diverges from conda-meta, do not pack as-is.")
        return 1
    print("result: ok - env matches conda-meta for packing.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
